async def _run_reused_report_branches(
    run_id: str,
    *,
    public_report: dict[str, Any],
    evidence: list[dict[str, Any]],
    answer_corpus: dict[str, Any],
    saved_illustrations: list[dict[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Refresh analysis and illustration copy without generating image files."""

    if not saved_illustrations:
        return await _final_report(run_id, public_report, answer_corpus), []

    async def build_refreshed_concepts() -> list[dict[str, Any]]:
        try:
            return await _illustration_concepts(
                run_id,
                public_report,
                evidence,
                answer_corpus["answers"],
            )
        except asyncio.CancelledError:
            raise
        except OpenRouterError as exc:
            logger.warning(
                "Illustration copy validation failed for saved run %s; "
                "using deterministic fallback (%s)",
                run_id,
                type(exc).__name__,
            )
            fallback = _fallback_reused_illustration_concepts()
            await _save_artifact(
                run_id,
                stage_key="report",
                artifact_key="illustration_concepts_fallback",
                status="completed",
                model=None,
                input_json={
                    "reason": "saved_asset_copy_validation_failed",
                    "source_version": ILLUSTRATION_CONCEPTS_VERSION,
                },
                output_json={"illustrations": fallback},
                prompt_version=ILLUSTRATION_COPY_FALLBACK_VERSION,
            )
            return fallback

    async with asyncio.TaskGroup() as task_group:
        final_task = task_group.create_task(
            _final_report(run_id, public_report, answer_corpus),
            name=f"aiv-report-reanalysis-{run_id}",
        )
        concepts_task = task_group.create_task(
            build_refreshed_concepts(),
            name=f"aiv-report-visual-copy-{run_id}",
        )

    return (
        final_task.result(),
        _reuse_saved_illustration_assets(
            saved_illustrations,
            concepts_task.result(),
        ),
    )


async def _run_report_branches(
    run_id: str,
    *,
    public_report: dict[str, Any],
    evidence: list[dict[str, Any]],
    answer_corpus: dict[str, Any],
    brand_name: str,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    async def build_visuals() -> list[dict[str, Any]]:
        try:
            concepts = await _illustration_concepts(
                run_id,
                public_report,
                evidence,
                answer_corpus["answers"],
            )
            await update_progress(
                run_id,
                stage="report",
                percent=89,
                detail="Визуальные концепции готовы. Создаём три инфографики.",
                eta_seconds=300,
            )
            illustrations = await _generate_illustrations(
                run_id,
                brand_name=brand_name,
                concepts=concepts,
                public_report=public_report,
            )
            await update_progress(
                run_id,
                stage="report",
                percent=97,
                detail="Визуальный слой готов. Завершаем аналитику.",
                eta_seconds=120,
            )
            return illustrations
        except asyncio.CancelledError:
            raise
        except Exception:
            logger.exception(
                "Illustration branch failed for run %s; publishing analysis",
                run_id,
            )
            return []

    async with asyncio.TaskGroup() as task_group:
        final_task = task_group.create_task(
            _final_report(
                run_id,
                public_report,
                answer_corpus,
            ),
            name=f"aiv-report-analysis-{run_id}",
        )
        illustrations_task = task_group.create_task(
            build_visuals(),
            name=f"aiv-report-visuals-{run_id}",
        )

    return final_task.result(), illustrations_task.result()


async def _review_technical_summary(
    run_id: str,
    technical: dict[str, Any],
) -> dict[str, Any]:
    return await _structured_artifact(
        run_id,
        stage_key="technical_access",
        artifact_key="technical_review",
        schema=TECHNICAL_REVIEW_SCHEMA,
        schema_name="aiv_technical_review",
        system=f"""
Проверь технический аудит сайта как старший специалист по доступности
контента для ИИ-краулеров. Работай только с переданными фактами.

Обязательные правила:
- форма входа не является стеной авторизации, если на странице есть
  содержательный основной текст;
- отсутствие данных — unknown, а не блокировка;
- CSR оценивай по исходному HTML, отдельно от SSR и статической выдачи;
- различай robots.txt, сетевую блокировку, WAF и пустую клиентскую оболочку;
- строки pages с is_utility=true — служебные подтверждения или технические
  адреса. Они показаны для прозрачности, но исключены из score и не должны
  превращаться в вывод о доступности содержательной части сайта;
- не меняй программно рассчитанный score;
- score — это индекс технической готовности по нескольким измеренным
  сигналам, а не процент доступности и не доказательство индексации;
- crawler user-agent пробы подтверждают только HTTP-ответ и читаемый HTML
  для имитированного user-agent. Не утверждай, что реальные системы уже
  обошли, проиндексировали или «прочитали» сайт;
- если у страницы body_truncated=true или structured_data_complete=false,
  отсутствие текста, разметки или признаков рендеринга на ней считается
  unknown. Не превращай усечённый ответ в отрицательный вывод;
- различай любую вспомогательную Schema.org-разметку и сущностные типы
  Organization, Product, Service, Article. Не пиши «Schema.org отсутствует»,
  если в structured_data_types присутствует хотя бы один тип;
- robots.state=partial означает частичные ограничения. Даже когда выбранные
  адреса разрешены, не называй robots.txt полностью открытым;
- связывай score только с coverage.evaluated_pages: пиши «на проверенных
  страницах», не распространяй результат на весь сайт;
- если coverage.coverage_state равно limited или unknown, назови ограничение
  в overall_conclusion и limitations; неизвестный полный размер сайта не
  означает полный охват;
- вывод связывай с тем, что сможет прочитать система и как это влияет на
  обнаружение бренда.

{LIVE_RUSSIAN_RULES}
""".strip(),
        user_payload=technical,
        prompt_version=TECHNICAL_REVIEW_VERSION,
    )


def _technical_editor_protected_terms(profile: dict[str, Any]) -> list[str]:
    protected = [str(profile.get("brand_name") or "").strip()]
    protected.extend(
        str(value or "").strip() for value in profile.get("brand_aliases") or []
    )
    protected.extend(
        str(value or "").strip() for value in profile.get("products") or []
    )
    catalog = profile.get("offer_catalog")
    if isinstance(catalog, dict):
        for offer in catalog.get("accepted_offers") or []:
            if not isinstance(offer, dict):
                continue
            protected.append(str(offer.get("canonical_name") or "").strip())
            protected.extend(
                str(value or "").strip() for value in offer.get("aliases") or []
            )
    return list(dict.fromkeys(value for value in protected if value))


def _technical_editorial_shape_is_safe(
    source: dict[str, Any],
    candidate: dict[str, Any],
) -> bool:
    """Prove that editorial output changed prose fields and nothing else."""

    if set(candidate) != set(source):
        return False
    source_findings = source.get("findings")
    candidate_findings = candidate.get("findings")
    if not isinstance(source_findings, list) or not isinstance(
        candidate_findings, list
    ):
        return False
    if len(source_findings) != len(candidate_findings):
        return False
    for source_row, candidate_row in zip(source_findings, candidate_findings):
        if not isinstance(source_row, dict) or not isinstance(candidate_row, dict):
            return False
        if set(candidate_row) != set(source_row):
            return False
        for key in source_row:
            if key in {"title", "business_effect", "action"}:
                if not isinstance(candidate_row.get(key), str):
                    return False
            elif candidate_row.get(key) != source_row.get(key):
                return False
    source_limits = source.get("limitations")
    candidate_limits = candidate.get("limitations")
    if not isinstance(source_limits, list) or not isinstance(candidate_limits, list):
        return False
    if len(source_limits) != len(candidate_limits) or not all(
        isinstance(value, str) for value in candidate_limits
    ):
        return False
    return all(
        isinstance(candidate.get(key), str)
        for key in ("overall_conclusion", "render_conclusion")
    )


async def _edit_technical_review_language(
    run_id: str,
    *,
    review: dict[str, Any],
    profile: dict[str, Any],
) -> dict[str, Any]:
    """Apply the audited Russian editorial harness to technical prose."""

    source = copy.deepcopy(review)
    protected_terms = _technical_editor_protected_terms(profile)
    profile_identity_sha256 = _stable_json_sha256(
        {
            "brand_name": profile.get("brand_name"),
            "brand_aliases": profile.get("brand_aliases") or [],
            "products": profile.get("products") or [],
        }
    )
    try:
        prose_paths = technical_review_narrative_paths(source)
        _source_units, source_manifest = build_editorial_units(
            source,
            prose_paths=prose_paths,
            protected_terms=protected_terms,
        )
    except Exception as exc:
        fallback_audit = seal_editorial_audit(
            {
                "version": REPORT_EDITOR_HARNESS_VERSION,
                "policy_version": REPORT_EDITOR_POLICY_VERSION,
                "policy_sha256": editorial_policy_sha256(),
                "source_report_sha256": _stable_json_sha256(source),
                "result_report_sha256": _stable_json_sha256(source),
                "coverage_complete": False,
                "fallback_reason": f"{type(exc).__name__}: {exc}",
            }
        )
        await _save_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key="technical_review_editorial",
            status="completed",
            model=PROCESSING_MODEL,
            input_json={
                "source_review_sha256": fallback_audit["source_report_sha256"],
                "profile_identity_sha256": profile_identity_sha256,
                "policy_version": REPORT_EDITOR_POLICY_VERSION,
                "policy_sha256": fallback_audit["policy_sha256"],
                "source_manifest_sha256": None,
                "prose_paths": [],
                "protected_terms": protected_terms,
            },
            output_json={"review": source, "audit": fallback_audit},
            error_message=str(exc),
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )
        return source
    cache_input = {
        "source_review_sha256": _stable_json_sha256(source),
        "profile_identity_sha256": profile_identity_sha256,
        "policy_version": REPORT_EDITOR_POLICY_VERSION,
        "policy_sha256": editorial_policy_sha256(),
        "source_manifest_sha256": source_manifest["manifest_sha256"],
        "prose_paths": prose_paths,
        "protected_terms": protected_terms,
    }
    cached = await _artifact_output(
        run_id,
        "technical_review_editorial",
        input_json=cache_input,
        model=PROCESSING_MODEL,
        prompt_version=TECHNICAL_EDITORIAL_VERSION,
    )
    if isinstance(cached, dict):
        cached_review = cached.get("review")
        cached_audit = cached.get("audit")
        if (
            isinstance(cached_review, dict)
            and isinstance(cached_audit, dict)
            and validate_editorial_cache(
                source,
                cached_review,
                cached_audit,
                prose_paths=prose_paths,
                protected_terms=protected_terms,
            )
            and _technical_editorial_shape_is_safe(source, cached_review)
        ):
            return copy.deepcopy(cached_review)

    async def editor_call(payload: dict[str, Any]) -> dict[str, Any]:
        value = copy.deepcopy(payload)
        value.pop("response_schema", None)
        attempt = int(value.get("attempt") or 0)
        unit_identity = _stable_json_sha256(
            {
                "source_unit_id": value.get("source_unit_id"),
                "source_sha256": value.get("source_sha256"),
            }
        )[:24]
        return await _structured_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key=f"technical_ru_editor_unit_a{attempt}_{unit_identity}",
            schema=EDITOR_UNIT_SCHEMA,
            schema_name="aiv_technical_ru_editor_unit",
            system=EDITORIAL_POLICY,
            user_payload=value,
            model=PROCESSING_MODEL,
            reasoning_effort="high",
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )

    async def critic_call(payload: dict[str, Any]) -> dict[str, Any]:
        value = copy.deepcopy(payload)
        value.pop("response_schema", None)
        digest = _stable_json_sha256(value)[:24]
        return await _structured_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key=f"technical_ru_editor_critic_{digest}",
            schema=EDITOR_CRITIC_SCHEMA,
            schema_name="aiv_technical_ru_editor_critic",
            system=EDITOR_CRITIC_POLICY,
            user_payload=value,
            model=REPORT_SEMANTIC_MODEL,
            reasoning_effort="high",
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )

    async def arbiter_call(payload: dict[str, Any]) -> dict[str, Any]:
        value = copy.deepcopy(payload)
        value.pop("response_schema", None)
        digest = _stable_json_sha256(value)[:24]
        return await _structured_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key=f"technical_ru_editor_arbiter_{digest}",
            schema=EDITOR_UNIT_SCHEMA,
            schema_name="aiv_technical_ru_editor_arbiter",
            system=(
                EDITORIAL_POLICY + "\n\nТы старший арбитр. Исправь только доказанный "
                "редакционный или смысловой дефект; факты неизменны."
            ),
            user_payload=value,
            model=ANALYSIS_MODEL,
            reasoning_effort="high",
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )

    await _save_artifact(
        run_id,
        stage_key="technical_access",
        artifact_key="technical_review_editorial",
        status="running",
        model=PROCESSING_MODEL,
        input_json=cache_input,
        prompt_version=TECHNICAL_EDITORIAL_VERSION,
    )
    try:
        edited, audit = await edit_report(
            source,
            editor_call=editor_call,
            critic_call=critic_call,
            arbiter_call=arbiter_call,
            prose_paths=prose_paths,
            protected_terms=protected_terms,
            concurrency=max(1, min(4, PROCESSING_BATCH_CONCURRENCY)),
        )
        if not _technical_editorial_shape_is_safe(source, edited):
            audit["semantic_fallback"] = {
                "used": True,
                "errors": ["technical_review_non_prose_fields_changed"],
            }
            edited = source
            audit["result_report_sha256"] = _stable_json_sha256(edited)
            audit["changed_paths"] = []
        else:
            audit["semantic_fallback"] = {"used": False, "errors": []}
        audit = seal_editorial_audit(audit)
        await _save_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key="technical_review_editorial",
            status="completed",
            model=PROCESSING_MODEL,
            input_json=cache_input,
            output_json={"review": edited, "audit": audit},
            raw_text=json.dumps(edited, ensure_ascii=False),
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )
        return edited
    except Exception as exc:
        fallback_audit = {
            "version": REPORT_EDITOR_HARNESS_VERSION,
            "policy_version": REPORT_EDITOR_POLICY_VERSION,
            "policy_sha256": editorial_policy_sha256(),
            "source_report_sha256": cache_input["source_review_sha256"],
            "result_report_sha256": _stable_json_sha256(source),
            "coverage_complete": False,
            "source_manifest": source_manifest,
            "fallback_reason": f"{type(exc).__name__}: {exc}",
        }
        fallback_audit = seal_editorial_audit(fallback_audit)
        await _save_artifact(
            run_id,
            stage_key="technical_access",
            artifact_key="technical_review_editorial",
            status="completed",
            model=PROCESSING_MODEL,
            input_json=cache_input,
            output_json={"review": source, "audit": fallback_audit},
            error_message=str(exc),
            prompt_version=TECHNICAL_EDITORIAL_VERSION,
        )
        return source


async def _prepare_analysis_foundation(
    run_id: str,
    *,
    allow_legacy_snapshot: bool = False,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    """Build independent technical and semantic foundations in parallel."""

    async with SessionLocal() as session:
        domain = (
            await session.execute(select(Run.domain).where(Run.id == run_id))
        ).scalar_one()
    try:
        crawl_admission = await require_crawl_admission(
            run_id,
            domain=domain,
            allow_legacy_snapshot=allow_legacy_snapshot,
        )
    except CrawlAdmissionIncomplete:
        if not allow_legacy_snapshot:
            raise
        crawl_admission = await bootstrap_legacy_crawl_admission(
            run_id,
            domain=domain,
        )

    technical, site_context = await asyncio.gather(
        _technical_summary(run_id),
        _site_context(run_id),
    )
    site_context["crawl_admission"] = copy.deepcopy(crawl_admission)
    async with asyncio.TaskGroup() as task_group:
        technical_review_task = task_group.create_task(
            _review_technical_summary(run_id, technical),
            name=f"aiv-technical-review-{run_id}",
        )
        profile_task = task_group.create_task(
            _classify_site(run_id, site_context),
            name=f"aiv-site-profile-{run_id}",
        )
    profile, _catalog, _clusters = await _bind_offer_catalog(
        run_id,
        profile_task.result(),
        site_context,
    )
    technical_review = await _edit_technical_review_language(
        run_id,
        review=technical_review_task.result(),
        profile=profile,
    )
    return (
        technical,
        technical_review,
        profile,
        site_context,
    )


async def _uses_canonical_intent_taxonomy(run_id: str) -> bool:
    """Keep saved legacy answers labeled by the taxonomy that produced them."""

    async with SessionLocal() as session:
        version = (
            await session.execute(
                select(RunArtifact.prompt_version).where(
                    RunArtifact.run_id == run_id,
                    RunArtifact.artifact_key == "prompt_set",
                )
            )
        ).scalar_one_or_none()
    return version in CANONICAL_INTENT_PROMPT_SET_VERSIONS


async def _final_analysis_foundation_context(run_id: str) -> dict[str, Any]:
    """Load internal provenance for the author without publishing metadata."""

    keys = (
        "offer_catalog",
        "prompt_foundation",
        "answer_set_receipt",
        "legacy_prompt_foundation_audit",
        "legacy_answer_foundation_audit",
    )
    async with SessionLocal() as session:
        artifacts = list(
            (
                await session.execute(
                    select(RunArtifact).where(
                        RunArtifact.run_id == run_id,
                        RunArtifact.artifact_key.in_(keys),
                        RunArtifact.status == "completed",
                    )
                )
            ).scalars()
        )
    return {
        artifact.artifact_key: copy.deepcopy(artifact.output_json)
        for artifact in artifacts
        if isinstance(artifact.output_json, dict)
    }


async def _finish_saved_answer_analysis(
    run_id: str,
    *,
    profile: dict[str, Any],
    technical: dict[str, Any],
    technical_review: dict[str, Any],
    regenerate_illustrations: bool = True,
) -> None:
    catalog_answers = await _answers_for_catalog(run_id)
    if not catalog_answers:
        raise OpenRouterError("No saved model answers are available for reanalysis")
    catalog = await _entity_catalog(run_id, profile, catalog_answers)
    await _annotate_answers(run_id, profile, catalog)
    rows = await _metric_rows(
        run_id,
        annotation_input_sha256=_annotation_context_sha256(profile, catalog),
    )
    metrics = _compute_metrics(rows, profile, catalog)
    expected_corpus_cells = await _expected_corpus_cells(run_id, rows)
    catalog, rows, metrics, critic_gate = await _run_analysis_critic_loop(
        run_id,
        profile=profile,
        catalog=catalog,
        rows=rows,
        metrics=metrics,
        expected_corpus_cells=expected_corpus_cells,
    )
    await _save_artifact(
        run_id,
        stage_key="knowledge_gap",
        artifact_key="metrics",
        status="completed",
        model=None,
        prompt_version=METRICS_VERSION,
        input_json={
            "annotation_digest": _stable_json_sha256(
                [
                    {
                        "answer_id": row["answer_id"],
                        "annotation": row["annotation"],
                    }
                    for row in rows
                ]
            ),
            "critic_gate_digest": _stable_json_sha256(critic_gate),
        },
        output_json=metrics,
    )
    public_report = _build_public_report(
        profile=profile,
        technical=technical,
        technical_review=technical_review,
        metrics=metrics,
        canonical_intent_taxonomy=await _uses_canonical_intent_taxonomy(run_id),
    )
    final_input_report = copy.deepcopy(public_report)
    final_input_report[
        "_analysis_foundation"
    ] = await _final_analysis_foundation_context(run_id)
    await update_progress(
        run_id,
        stage="report",
        percent=82,
        detail=(
            "Параллельно собираем аналитику и три визуальные концепции."
            if regenerate_illustrations
            else "Пересобираем расчёты и интерпретацию из сохранённых ответов."
        ),
        eta_seconds=360,
    )
    evidence = await _evidence_sample(run_id)
    answer_corpus = await _full_answer_context(
        run_id,
        critic_gate=critic_gate,
        critic_rows=rows,
        expected_corpus_cells=expected_corpus_cells,
    )
    if regenerate_illustrations:
        final, illustrations = await _run_report_branches(
            run_id,
            public_report=final_input_report,
            evidence=evidence,
            answer_corpus=answer_corpus,
            brand_name=str(profile.get("brand_name") or "бренд"),
        )
    else:
        async with SessionLocal() as session:
            saved_report = (
                await session.execute(select(Run.report_json).where(Run.id == run_id))
            ).scalar_one_or_none()
        saved_illustrations = (
            copy.deepcopy(saved_report.get("illustrations") or [])
            if isinstance(saved_report, dict)
            else []
        )
        final, illustrations = await _run_reused_report_branches(
            run_id,
            public_report=final_input_report,
            evidence=evidence,
            answer_corpus=answer_corpus,
            saved_illustrations=saved_illustrations,
        )
    markdown = _render_markdown(final)
    site_preview = await get_saved_site_preview(run_id)
    report_json = {
        **public_report,
        "narrative": {
            "headline": final.get("headline"),
            "headline_emphasis": final.get("headline_emphasis") or [],
            "verdict": final.get("verdict"),
            "executive_summary": final.get("executive_summary"),
            "actions": final.get("actions") or [],
        },
        "illustrations": illustrations,
        **({"site_preview": site_preview} if site_preview else {}),
    }
    owner = lease_owner_for(run_id)
    report_conditions = [Run.id == run_id]
    if owner is not None:
        report_conditions.extend(
            (
                Run.execution_slot == 1,
                Run.lease_owner == owner,
                Run.status.in_(
                    (
                        RunStatus.pending,
                        RunStatus.crawling,
                        RunStatus.analyzing,
                    )
                ),
            )
        )
    async with SessionLocal() as session:
        saved = await session.execute(
            update(Run)
            .where(*report_conditions)
            .values(
                analysis_markdown=markdown,
                report_json=report_json,
            )
            .returning(Run.id)
        )
        saved_run_id = saved.scalar_one_or_none()
        if saved_run_id is None:
            await session.rollback()
        else:
            if not regenerate_illustrations:
                await _synchronize_reused_illustration_metadata(
                    session,
                    run_id=run_id,
                    illustrations=illustrations,
                )
            await session.commit()
    if saved_run_id is None:
        if owner is not None:
            raise RunLeaseLostError(f"Run lease lost for {run_id}")
        raise LookupError(f"Run not found: {run_id}")
    completed = await complete_run(run_id)
    if not completed:
        if owner is not None:
            raise RunLeaseLostError(
                f"Run lease lost before terminal completion for {run_id}"
            )
        raise LookupError(f"Run could not be completed: {run_id}")


async def reprocess_saved_answers(run_id: str) -> None:
    """Rebuild annotations, metrics and report without calling the model panel."""

    try:
        await update_progress(
            run_id,
            stage="knowledge_gap",
            percent=70,
            detail="Переанализируем сохранённые ответы без повторного опроса моделей.",
            eta_seconds=720,
            status=RunStatus.analyzing,
        )
        (
            technical,
            technical_review,
            profile,
            _site_context_value,
        ) = await _prepare_analysis_foundation(
            run_id,
            allow_legacy_snapshot=True,
        )
        await _save_answer_set_receipt(run_id)
        await _finish_saved_answer_analysis(
            run_id,
            profile=profile,
            technical=technical,
            technical_review=technical_review,
            regenerate_illustrations=False,
        )
    except asyncio.CancelledError:
        raise
    except Exception:
        logger.exception("Saved-answer reanalysis failed for run %s", run_id)
        await fail_run(
            run_id,
            "Не удалось завершить переанализ сохранённых ответов. "
            "Исходные ответы остались в базе.",
        )


async def analyze_run(run_id: str) -> None:
    try:
        await update_progress(
            run_id,
            stage="scenario_design",
            percent=28,
            detail="Определяем бренд, продукты и реальные задачи выбора.",
            eta_seconds=1080,
            status=RunStatus.analyzing,
        )
        await apply_ua_conditional_block(run_id)
        # Validate the persisted nine-prompt panel checkpoint before any
        # upstream model work or artifact writes. Provenance validation still
        # follows below, but a DB/artifact mismatch must fail at the cheapest,
        # read-only boundary.
        panel_checkpoint = await _load_panel_resume_checkpoint(run_id)
        (
            technical,
            technical_review,
            profile,
            site_context,
        ) = await _prepare_analysis_foundation(run_id)
        if panel_checkpoint is None:
            await update_progress(
                run_id,
                stage="scenario_design",
                percent=31,
                detail="Проверяем рынок, аудитории и критерии выбора по источникам.",
                eta_seconds=960,
            )
            market_research = await _market_research(
                run_id,
                profile,
                site_context,
            )
            await update_progress(
                run_id,
                stage="scenario_design",
                percent=34,
                detail="Строим сценарии из подтверждённых задач выбора.",
                eta_seconds=840,
            )
            prompt_set = await _generate_prompt_set(
                run_id,
                profile,
                site_context.get("requested_site"),
                market_research=market_research,
            )
            await _save_prompt_foundation(
                run_id,
                profile=profile,
                market_research=market_research,
                site_context=site_context,
                prompt_set=prompt_set,
            )
            prompts = await _persist_prompts(run_id, prompt_set)
        else:
            await _validate_panel_foundation_resume(
                run_id,
                profile=profile,
                site_context=site_context,
            )
            prompts = panel_checkpoint
            await update_progress(
                run_id,
                stage="scenario_design",
                percent=34,
                detail="Продолжаем с сохранёнными сценариями и ответами.",
                eta_seconds=840,
            )
        await update_progress(
            run_id,
            stage="web_visibility",
            percent=38,
            detail="Запрашиваем независимые ответы с актуальным веб-поиском.",
            eta_seconds=900,
        )
        await _run_panel(
            run_id,
            prompts,
            mode="web",
            start_percent=38,
            end_percent=64,
        )
        await update_progress(
            run_id,
            stage="knowledge_gap",
            percent=65,
            detail="Проверяем знания моделей без веб-поиска.",
            eta_seconds=600,
        )
        await _run_panel(
            run_id,
            prompts,
            mode="memory",
            start_percent=65,
            end_percent=72,
        )
        await _save_answer_set_receipt(run_id)
        await _finish_saved_answer_analysis(
            run_id,
            profile=profile,
            technical=technical,
            technical_review=technical_review,
        )
    except asyncio.CancelledError:
        raise
    except PanelCheckpointMismatchError as exc:
        logger.error("Panel checkpoint rejected for run %s: %s", run_id, exc)
        await fail_run(
            run_id,
            "Продолжение остановлено: сохранённые сценарии и ответы не прошли "
            "проверку целостности. Исходные ответы не изменены; нужна "
            "операторская проверка.",
        )
    except Exception:
        logger.exception("AIV analysis failed for run %s", run_id)
        await fail_run(
            run_id,
            "Проверка прервалась во время анализа. Нажмите «Продолжить»: "
            "сервис использует уже сохранённые ответы и завершит недостающие этапы.",
        )
